// ProductMarket godoc
// @Summary 장터 API
// @Description 장터상품 '팝니다' 및 '무료로 드립니다' 의 상품명, 가격등의 데이터를 제공
// @Tags market : 장터 API
// @Accept json
// @Produce json
// @Param keyword query string true "키워드"
// @Param method query string false "<table><thead><tr><th colspan=2>검색 키워드 방법</th></tr></thead><tbody><tr><td>제목</td><td>prodN</td></tr><tr><td>내용</td><td>contents</td></tr><tr><td>사용자 ID</td><td>userId</td></tr></tbody></table>" Enums(prodN, contents, userId) default(prodN)
// @Param reKeyword query string false "재검색 키워드"
// @Param subKeyword query string false "추가검색 키워드"
// @Param reMethod query string false "<table><thead><tr><th colspan=2>재검색 키워드 방법</th></tr></thead><tbody><tr><td>제목</td><td>prodN</td></tr><tr><td>내용</td><td>contents</td></tr><tr><td>사용자 ID</td><td>userId</td></tr></tbody></table>" Enums(prodN, contents, userId) default(prodN)
// @Param newProd query string false "<table><thead><tr><th colspan=2>새제품 여부</th></tr></thead><tbody><tr><td>중고</td><td>N</td></tr><tr><td>새제품</td><td>Y</td></tr></tbody></table>" Enums(Y,N)
// @Param buyWay query string false "<table><thead><tr><th colspan=2>결재방법</th></tr></thead><tbody><tr><td>일반 직거래</td><td>N</td></tr><tr><td>유니크로</td><td>U</td></tr><tr><td>에스크로</td><td>E</td></tr><tr><td>ipay</td><td>I</td></tr></tbody></table>" Enums(N,U,E,I")
// @Param locale query int false "지역"
// @Param userLevel query string false "<table><thead><tr><th colspan=2>사업자 구분</th></tr></thead><tbody><tr><td>사업자</td><td>B</td></tr><tr><td>미니샵</td><td>M</td></tr><tr><td>일반</td><td>N</td></tr><tr><td colspan=2>복수값 사용 가능.<br>구분자 "|" 사용.(예:B|M)</td></tr></tbody></table>" string
// @Param cate1 query int false "대분류"
// @Param cate2 query int false "중분류"
// @Param cate3 query int false "소분류"
// @Param cate4 query int false "세분류"
// @Param minPrice query int false "특정 가격 이상 검색"
// @Param maxPrice query int false "특정 가격 이하 검색"
// @Param userId query string false "사용자 아이디" string
// @Param sort query string false "<table><thead><tr><th colspan=2>필드|정렬</th></tr></thead><tbody><tr><td>필드</td></tr><tr><td>날짜</td><td>1</td></tr><tr><td>가격</td><td>2</td></tr><tr><td>정렬</td></tr><tr><td>ASC(오름차순)</td><td>1</td></tr><tr><td>DESC(내림차순)</td><td>2</td></tr></tbody></table>"
// @Param group query string false "<table><thead><tr><th colspan=2>분류</th></tr></thead><tbody><tr><td>판매</td><td>S</td></tr><tr><td>무료</td><td>F</td></tr></tbody></table>" Enums(S,F) default(S)
// @Param status query string false "판매(group=S) 분류시 -> 판매중 : N, 예약중 : R, 판매완료 : Y<br>무료(group=F) 분류시 -> 진행 : N, 완료 : Y" Enums(N,R,Y)
// @Param start query int false "시작 번호"  default(1)
// @Param limit query int false "결과 개수"  default(1)
// @Param highlightYN  query string false "<table><thead><tr><th colspan=2>하이라이팅 적용여부</th></tr></thead><tbody><tr><td>Y</td><td>적용</td></tr><tr><td>N</td><td>미적용</td></tr></tbody></table>" Enums(Y,N) default(Y)
// @Param synonymYN query string false "<table><thead><tr><th colspan=2>키워드 검색 동의어 사용 유무</th></tr></thead><tbody><tr><td>동의어 사용</td><td>Y</td></tr><tr><td>동의어 미사용</td><td>N</td></tr></tbody></table>" Enums(Y,N) default(Y)
// @Param saleType query string false "<table><thead><tr><th colspan=2>오픈마켓 구분</th></tr></thead><tbody><tr><td>다나와 일반 상품 검색</td><td>N</td></tr><tr><td>전체 중고 상품 검색 (G,I,A,S,N)</td><td>P</td></tr><tr><td>오픈마켓 상품 검색 (G,I,A,S)</td><td>O</td></tr><tr><td>지마켓 상품 검색</td><td>G</td></tr><tr><td>인터파크 상품 검색</td><td>I</td></tr><tr><td>옥션 상품 검색</td><td>A</td></tr><tr><td>11번가 상품 검색</td><td>S</td></tr>" Enums(N,P,O,G,I,A,S) default(N)
// @Param miniShop query string false "미니샵노출여부" Enums(B,M) default(B)
// @Param displayYN query string false "<table><thead><tr><th colspan=2>상품출력여부</th></tr></thead><tbody><tr><td>Y</td><td>출력</td></tr><tr><td>N</td><td>미출력</td></tr></tbody></table>" Enums(Y,N) default(Y)
// @Success 200 {object} response.Response
// @Router /market/product [get]
func (c *Controller) ProductMarket(ctx *gin.Context) {
	resp := response.Response{}

	if len(ctx.Query("keyword")) == 0 {
		resp.Status = http.StatusBadRequest
		resp.Desc = "keyword must required."

		ctx.JSON(http.StatusOK, resp)

		return
	}

	query := make(map[string]string)
	query["keyword"] = ctx.Query("keyword")
	if len(query["keyword"]) > 0 {
		query["method"] = ctx.DefaultQuery("method", "prodN")
	}
	query["cate1"] = ctx.Query("cate1")

	query["reKeyword"] = ctx.Query("reKeyword")
	if len(query["reKeyword"]) > 0 {
		query["reMethod"] = ctx.DefaultQuery("reMethod", "prodN")
	}

	query["subKeyword"] = ctx.Query("subKeyword")
	query["newProd"] = ctx.Query("newProd")
	query["buyWay"] = ctx.Query("buyWay")
	query["locale"] = ctx.Query("locale")
	query["userLevel"] = ctx.Query("userLevel")
	query["cate1"] = ctx.Query("cate1")
	query["cate2"] = ctx.Query("cate2")
	query["cate3"] = ctx.Query("cate3")
	query["cate4"] = ctx.Query("cate4")

	query["minPrice"] = ctx.Query("minPrice")
	query["maxPrice"] = ctx.Query("maxPrice")

	query["userId"] = ctx.Query("userId")
	query["sort"] = ctx.DefaultQuery("sort", "1|2") // order -> sort 변경

	query["status"] = ctx.Query("status")
	query["start"] = ctx.DefaultQuery("start", "1")
	query["limit"] = ctx.DefaultQuery("limit", "1")
	query["highlight"] = ctx.DefaultQuery("highlightYN", "Y")
	query["syn"] = ctx.DefaultQuery("synonymYN", "Y")
	query["group"] = ctx.DefaultQuery("group", "S")
	query["saleType"] = ctx.DefaultQuery("saleType", "N")
	query["miniShop"] = ctx.DefaultQuery("miniShop", "B")
	query["display"] = ctx.DefaultQuery("displayYN", "Y")
	query["debug"] = ctx.DefaultQuery("debug", "0")
	query["userAgent"] = ctx.GetHeader("User-Agent")
	query["referer"] = ctx.GetHeader("Referer")

	if result, err := handler.EsProductMarket(query); err != nil {
		resp.Status = http.StatusInternalServerError
		resp.Desc = err.Error()
	} else {
		resp.Status = http.StatusOK
		resp.Result = result
	}

	resp.Keyword = ctx.Query("keyword")

	ctx.JSON(http.StatusOK, resp)
}

package handler

import (
	"context"
	"encoding/json"
	"strconv"
	"strings"

	"github.com/mitchellh/mapstructure"
	elasticSearch "github.com/olivere/elastic/v7"

	"svn.danawa.com/sapi/common/utils"
	"svn.danawa.com/sapi/elasticConn"
	"svn.danawa.com/sapi/manager/market"
	"svn.danawa.com/sapi/model"
	"svn.danawa.com/sapi/response"
)

func EsProductMarket(param map[string]string) (result response.Result, err error) {
	//인덱스(volume)
	index := "market"

	//검색 시작값
	from, _ := strconv.Atoi(param["start"])
	from = from - 1
	//검색 갯수
	size, _ := strconv.Atoi(param["limit"])

	debug := utils.CheckIntData(param["debug"])

	query := market.MarketBoolQuery(param)

	var raString []string
	var order bool
	sort := strings.Split(param["sort"], "|") // ex) 1|2 or 2|1 ..

	if len(sort) == 2 {
		raString = market.EsProductRa(sort)
	}
	if raString[1] == "ASC" {
		order = true
	} else {
		order = false
	}

	//하이라이팅
	var highlight *elasticSearch.Highlight
	if param["highlight"] == "Y" {
		highlight = MarketSetHighLight(param["keyword"])
	}

	fsc := elasticSearch.NewFetchSourceContext(true).Include(MarketProductSource()...)

	client := elasticConn.EsClient

	esSearch := client.Search().
		Query(query). // specify the query
		FetchSourceContext(fsc).
		Index(index). // search in index
		From(from).   // -1 처리(기존 1)
		Size(size).   // take documents 0-9
		Pretty(true). // pretty print request and response JSON
		TrackTotalHits(true).
		Timeout("5s")

	if highlight != nil {
		esSearch.Highlight(highlight)
	}

	if len(sort) == 2 {
		esSearch.Sort(raString[0], order) // sort
	}

	res, err := esSearch.Do(context.Background())
	if err == nil {
		// 로깅
		if debug == 1 {
			var mFsc string
			var mHighlight string
			var mQuery string
			var mSort string
			var mAggs string
			var mCollapse string

			mainQueryParam, _ := query.Source()
			mainQuery, _ := json.Marshal(mainQueryParam)
			mQuery = "\"query\" :" + string(mainQuery)

			if fsc != nil {
				SourceParam, _ := fsc.Source()
				source, _ := json.Marshal(SourceParam)
				mFsc = "\"_source\" :" + string(source)
			}

			if highlight != nil {
				highlightParam, _ := highlight.Source()
				highlightQuery, _ := json.Marshal(highlightParam)
				mHighlight = "\"highlight\" :" + string(highlightQuery)
			}

			if len(sort) == 2 {
				if order == true {
					mSort = "\"sort\" : [ { \"" + raString[0] + "\": {" + "\"order\": \"ASC\"}}]"
				} else {
					mSort = "\"sort\" : [ { \"" + raString[0] + "\": {" + "\"order\": \"DESC\"} } ]"
				}
			}

			utils.WriteEsQueryDebugLog(index, strconv.Itoa(from), strconv.Itoa(size), mQuery, mFsc, mHighlight, mSort, mAggs, mCollapse)
		}

		resultSlice := make([]interface{}, 0)

		for _, value := range res.Hits.Hits {
			resultData := make(map[string]interface{}, 0)
			json.Unmarshal([]byte(value.Source), &resultData)

			//하이라이팅 있을시 교체
			if value.Highlight != nil {
				//fmt.Println(element.Highlight)

				for i, highlightValue := range value.Highlight {
					resultData[i] = highlightValue[0]
					//fmt.Println(i, " : ", value[0])
				}
			}

			marketProductEs := &model.MarketProductEs{}
			mapstructure.Decode(resultData, &marketProductEs)

			if len(marketProductEs.TInputDate) > 0 {
				marketProductEs.TInputDate = strings.Split(marketProductEs.TInputDate, " ")[0]
			}

			marketProduct := &model.MarketProduct{}
			marketProduct.SEQ, _ = strconv.Atoi(marketProductEs.Seq)
			marketProduct.CATEGORYCODE1, _ = strconv.Atoi(marketProductEs.CategoryCode1)
			marketProduct.CATEGORYCODE2, _ = strconv.Atoi(marketProductEs.CategoryCode2)
			marketProduct.CATEGORYCODE3, _ = strconv.Atoi(marketProductEs.CategoryCode3)
			marketProduct.CATEGORYCODE4, _ = strconv.Atoi(marketProductEs.CategoryCode4)
			marketProduct.LOCALECODE1, _ = strconv.Atoi(marketProductEs.LocaleCode1)
			marketProduct.LOCALECODE2, _ = strconv.Atoi(marketProductEs.LocaleCode2)
			marketProduct.LOCALECODE3, _ = strconv.Atoi(marketProductEs.LocaleCode3)
			marketProduct.PRODUCTCODE, _ = strconv.Atoi(marketProductEs.ProductCode)
			marketProduct.MEMBER_SEQ, _ = strconv.Atoi(marketProductEs.Member_seq)
			marketProduct.PRICE, _ = strconv.Atoi(marketProductEs.Price)
			marketProduct.STOCK, _ = strconv.Atoi(marketProductEs.Stock)
			marketProduct.COMMENT, _ = strconv.Atoi(marketProductEs.Comment)
			marketProduct.VIEW, _ = strconv.Atoi(marketProductEs.View)
			marketProduct.GPS_LAT, _ = strconv.ParseFloat(marketProductEs.Gps_lat, 64)
			marketProduct.GPS_LON, _ = strconv.ParseFloat(marketProductEs.Gps_lon, 64)
			mapstructure.Decode(marketProductEs, &marketProduct)

			resultSlice = append(resultSlice, marketProduct)
		}

		result.Total_count = int(res.Hits.TotalHits.Value)
		result.Time = utils.GetEsSearchtimeFormat(res.TookInMillis)
		result.Count = len(resultSlice)
		result.SearchList = resultSlice
	} else {
		logger.Error(err.Error())
	}

	return
}

func MarketProductSource() []string {
	return []string{"seq", "categoryCode1", "categoryCode2", "categoryCode3", "categoryCode4",
		"localeCode1", "localeCode2", "localeCode3", "productCode", "use_img",
		"productName", "user_id", "user_name", "member_seq", "price",
		"buyWay", "stock", "newProd", "comment", "view", "userLevel", "tInputDate",
		"prod_status", "originPlatform", "gps_lat", "gps_lon",
		"saleType", "linkProductCode", "linkProductUrl"}
}

//하이라이팅
func MarketSetHighLight(keyword string) (hightlight *elasticSearch.Highlight) {

	fields := []string{
		"productName",
		"contents",
		"user_id"}

	var highlightFieldArr []*elasticSearch.HighlighterField
	for _, field := range fields {
		highlightFieldArr = append(highlightFieldArr, elasticSearch.NewHighlighterField(field))
	}

	hightlight = elasticSearch.NewHighlight().Fields(highlightFieldArr...).RequireFieldMatch(false).NumOfFragments(0).PreTags("<b>").PostTags("</b>")

	return

}

