package market

import (
	elasticSearch "github.com/olivere/elastic/v7"

)

func MarketBoolQuery(param map[string]string) *elasticSearch.BoolQuery {
	//BoolQuery 생성
	query := elasticSearch.NewBoolQuery()

	//bool Query 배열
	var mustMatchQueryList []elasticSearch.Query
	var filterTermQueryList []elasticSearch.Query

	searchQuery, mustNotMatchQueryList := KeywordQuery(param)

	if len(param["saleType"]) > 0 && param["saleType"] != "P" {
		if param["saleType"] == "O" {
			saleTypeMatchQuery := elasticSearch.NewMatchQuery("saleType", "N")
			mustNotMatchQueryList = append(mustNotMatchQueryList, saleTypeMatchQuery)
		} else {
			saleTypeTermQuery := elasticSearch.NewTermQuery("saleType", param["saleType"])
			filterTermQueryList = append(filterTermQueryList, saleTypeTermQuery)
		}
	}

	if searchQuery != nil {
		filterTermQueryList = append(filterTermQueryList, searchQuery)
	}

	if len(mustMatchQueryList) > 0 {
		query.Must(mustMatchQueryList...)
	}
	if len(mustNotMatchQueryList) > 0 {
		query.MustNot(mustNotMatchQueryList...)
	}
	if len(EsProductFt(param)) > 0 {
		for _, value := range EsProductFt(param) {
			filterTermQueryList = append(filterTermQueryList, value)
		}
	}
	if len(filterTermQueryList) > 0 {
		query.Filter(filterTermQueryList...)
	}

	return query
}

package market

import (
	"strings"

	elasticSearch "github.com/olivere/elastic/v7"

	"svn.danawa.com/sapi/common/utils"
)

func KeywordQuery(param map[string]string) (keywordQuery elasticSearch.Query, mustNotMatchQueryList []elasticSearch.Query) {

	var searchIndex string
	switch param["method"] {
	case "prodN":
		searchIndex = "productName"
	case "userId":
		searchIndex = "user_id"
	case "contents":
		searchIndex = "contents"
	default:
		searchIndex = "productName"
	}

	keyword := utils.FilteringKeyword(param["keyword"])

	//추가 단어 검색 - 원래 키워드와 합치자(AND)
	if len(param["reKeyword"]) > 0 {
		keyword = keyword + " " + param["reKeyword"]
	}

	var expendList utils.ExpendList
	if param["syn"] == "Y" {
		expendList = utils.PostExpansionKeyword(keyword, true, true)
	} else {
		expendList = utils.PostExpansionKeyword(keyword, false, true)
	}

	var subKeywords string
	if len(param["subKeyword"]) > 0 {
		subKeywordList := strings.Split(param["subKeyword"], "|")
		list := make([]string, 0)
		for _, subKeyword := range subKeywordList {
			if subKeyword != "" {
				if strings.HasPrefix(subKeyword, "!") {
					//제외 키워드는 그냥 must not으로 (동의어 확장 안함)
					subKeyword = strings.TrimSpace(strings.ReplaceAll(subKeyword, "!", ""))
					excludeKeyword := elasticSearch.NewMatchQuery(searchIndex, utils.FilteringKeyword(subKeyword))
					mustNotMatchQueryList = append(mustNotMatchQueryList, excludeKeyword)
				} else {
					//추가해야할 키워드는 별도 키워드로 생성 (동의어 확장)
					subKeyword = strings.TrimSpace(subKeyword)
					list = append(list, subKeyword)
				}
			}
		}
		subKeywords = strings.Join(list, "|")
	}

	subKeywords = utils.FilteringKeyword(subKeywords)

	keywordQuery,_ = utils.GetEsSearchQuery(searchIndex, expendList.Result, expendList.Synonym, subKeywords, false)

	return
}

