	} else if inputDate == "2" { // 가격
		if price == "1" {
			raString = append(raString, "price")
			raString = append(raString, "ASC")
		} else {
			raString = append(raString, "price")
			raString = append(raString, "DESC")
		}
	} else { // default
		raString = append(raString, "tInputDate")
		raString = append(raString, "ASC")
	}

	return
}

